// Contract for AI-drafted recipes (SS-053). A draft is generated by Gemini
// from the cook's confirmed pantry items when no reviewed recipe fits. It is
// always labelled as unreviewed and passes validation and safety rules before
// the live coach can use it.

import '../core/models.dart';

/// Recipe IDs for drafts start with this prefix so every surface can label
/// them as AI-drafted and unreviewed.
const kDraftRecipePrefix = 'draft_';

bool isDraftRecipe(Recipe recipe) => recipe.id.startsWith(kDraftRecipePrefix);

/// Shown wherever a drafted recipe appears.
const kDraftRecipeLabel = 'AI-drafted recipe · not reviewed';

class RecipeDraftRequest {
  const RecipeDraftRequest({required this.confirmedItems, this.note = ''});

  /// Items the cook explicitly confirmed (never unconfirmed candidates).
  final List<String> confirmedItems;

  /// Optional free text from the cook, e.g. "I want pizza".
  final String note;
}

class RecipeDraftException implements Exception {
  const RecipeDraftException(this.message);

  /// Safe, cook-facing message.
  final String message;
  @override
  String toString() => message;
}

abstract class RecipeDraftClient {
  /// Returns a validated draft [Recipe] whose id starts with
  /// [kDraftRecipePrefix], or throws [RecipeDraftException].
  Future<Recipe> draft(RecipeDraftRequest request);
}
